package ai.karma.video;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.view.*;
public class MainActivity extends Activity {
 WebView home,browser; LinearLayout root; ValueCallback<Uri[]> pending; boolean external=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(0,getResources().getIdentifier("status_bar_height","dimen","android")>0?getResources().getDimensionPixelSize(getResources().getIdentifier("status_bar_height","dimen","android")):0,0,0);Button back=new Button(this);back.setText("KARMA • Retour au studio");root.addView(back);Button open=new Button(this);open.setText("Ouvrir dans le navigateur système");root.addView(open);open.setOnClickListener(v->{String url=browser.getUrl();if(external&&url!=null&&url.startsWith("https://")){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"Navigateur indisponible",1).show();}}else Toast.makeText(this,"Choisis d’abord un moteur",0).show();});home=new WebView(this);browser=new WebView(this);setup(home);setup(browser);root.addView(home,new LinearLayout.LayoutParams(-1,0,1));root.addView(browser,new LinearLayout.LayoutParams(-1,0,1));browser.setVisibility(View.GONE);back.setOnClickListener(v->showHome());setContentView(root);home.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())){external=true;home.setVisibility(View.GONE);browser.setVisibility(View.VISIBLE);browser.loadUrl(u.toString());return true;}return !"file".equals(u.getScheme());}});home.addJavascriptInterface(new LocalClipboard(),"KarmaClipboard");home.loadUrl("file:///android_asset/index.html");}
 private class LocalClipboard { @JavascriptInterface public void copy(String value){runOnUiThread(()->{android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("Prompt KARMA",value));});} }
 void showHome(){external=false;browser.setVisibility(View.GONE);home.setVisibility(View.VISIBLE);}
 void setup(WebView w){WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);w.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme());}});w.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(pending!=null)pending.onReceiveValue(null);pending=cb;try{startActivityForResult(p.createIntent(),12);}catch(Exception e){pending.onReceiveValue(null);pending=null;}return true;}});w.setDownloadListener((url,ua,disposition,mime,len)->{try{if(!"https".equals(Uri.parse(url).getScheme()))throw new IllegalArgumentException();DownloadManager.Request req=new DownloadManager.Request(Uri.parse(url));req.addRequestHeader("User-Agent",ua);String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)req.addRequestHeader("Cookie",cookie);req.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,disposition,mime));req.setNotificationVisibility(1);((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(req);Toast.makeText(this,"Téléchargement lancé",0).show();}catch(Exception e){Toast.makeText(this,"Téléchargement non pris en charge : utiliser le navigateur",1).show();}});}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==12&&pending!=null){pending.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));pending=null;}}
 @Override public void onBackPressed(){if(external){if(browser.canGoBack())browser.goBack();else showHome();}else super.onBackPressed();}
}
